<script setup lang="ts">
import { useMessage } from 'naive-ui'
definePageMeta({ layout: 'admin' }); useSeoMeta({ title: '数据统计' })
type Point = { x: string; y: number }
type Analytics = { metricUnits?: { url: 'visitors' | 'pageviews'; sessions: 'visitors' | 'sessions' }; status: 'available' | 'unconfigured' | 'unavailable'; message?: string; overview?: Record<string, { value: number; prev?: number }>; trend?: { pageviews?: Point[]; sessions?: Point[] }; hourly?: { pageviews?: Point[]; sessions?: Point[] }; referrer?: Point[]; device?: Point[]; browser?: Point[]; url?: Point[] }
const end = ref(new Date().toLocaleDateString('sv-SE', { timeZone: 'Asia/Shanghai' })), start = ref(new Date(Date.now() - 29 * 86400000).toLocaleDateString('sv-SE', { timeZone: 'Asia/Shanghai' }))
const selected = ref({ start: start.value, end: end.value }), message = useMessage()
const { data, status, error, refresh } = await useFetch<Analytics>('/api/admin/analytics/overview', { query: selected })
const config = useRuntimeConfig()
const cloudTracking = computed(() => {
  try { return new URL(config.public.umamiScriptUrl).origin === 'https://cloud.umami.is' && !!config.public.umamiWebsiteId } catch { return false }
})
const cloudWithoutApi = computed(() => cloudTracking.value && data.value?.status === 'unconfigured')
const pathMetricLabel = computed(() => data.value?.metricUnits?.url === 'visitors' ? '访客数' : '浏览量')
const seriesMetricLabel = computed(() => data.value?.metricUnits?.sessions === 'visitors' ? '访客数 UV' : '会话数')
const metrics = [{ key: 'pageviews', name: '浏览量 PV' }, { key: 'visitors', name: '访客数 UV' }, { key: 'visits', name: '会话数' }]
function range(days: number) { end.value = new Date().toLocaleDateString('sv-SE', { timeZone: 'Asia/Shanghai' }); start.value = new Date(Date.now() - (days - 1) * 86400000).toLocaleDateString('sv-SE', { timeZone: 'Asia/Shanghai' }); selected.value = { start: start.value, end: end.value } }
function query() { if (!start.value || !end.value || start.value > end.value || (Date.parse(end.value) - Date.parse(start.value)) / 86400000 > 365) { message.error('请选择 1 至 366 天的有效日期范围'); return } selected.value = { start: start.value, end: end.value } }
const trend = computed(() => ({ color: ['#879f68', '#c2b897'], tooltip: { trigger: 'axis' }, legend: { bottom: 0 }, grid: { left: 45, right: 20, top: 20, bottom: 60 }, xAxis: { type: 'category', data: (data.value?.trend?.pageviews || []).map(p => p.x.slice(5, 10)) }, yAxis: { type: 'value', minInterval: 1 }, series: [{ type: 'line', name: '浏览量 PV', smooth: true, areaStyle: { opacity: .1 }, data: (data.value?.trend?.pageviews || []).map(p => p.y) }, { type: 'line', name: seriesMetricLabel.value, smooth: true, data: (data.value?.trend?.sessions || []).map(p => p.y) }] }))
function pie(points: Point[]) { return { color: ['#839e63', '#a5b987', '#c7d0b2', '#cabca1', '#96947b'], tooltip: { trigger: 'item' }, legend: { bottom: 0, type: 'scroll' }, series: [{ type: 'pie', radius: ['42%', '65%'], center: ['50%', '43%'], label: { show: false }, data: points.map(p => ({ name: p.x || '直接访问', value: p.y })) }] } }
const heat = computed(() => {
  const cells = Array.from({ length: 7 * 24 }, (_, i) => [i % 24, Math.floor(i / 24), 0])
  for (const p of data.value?.hourly?.sessions || []) { const date = new Date(p.x.endsWith('Z') ? p.x : `${p.x}+08:00`); if (!Number.isNaN(date.getTime())) { const parts = new Intl.DateTimeFormat('en-US', { timeZone: 'Asia/Shanghai', weekday: 'short', hour: 'numeric', hourCycle: 'h23' }).formatToParts(date); const day = ['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].indexOf(parts.find(x => x.type === 'weekday')!.value); const hour = Number(parts.find(x => x.type === 'hour')!.value); if (day >= 0) cells[day * 24 + hour]![2]! += p.y } }
  return { tooltip: { position: 'top' }, grid: { left: 45, right: 20, top: 10, bottom: 65 }, xAxis: { type: 'category', data: Array.from({ length: 24 }, (_, i) => `${i}时`) }, yAxis: { type: 'category', data: ['周一','周二','周三','周四','周五','周六','周日'] }, visualMap: { min: 0, max: Math.max(1, ...cells.map(c => c[2]!)), calculable: false, orient: 'horizontal', left: 'center', bottom: 0, inRange: { color: ['#eef2e5','#c3d5ac','#779d52'] } }, series: [{ type: 'heatmap', data: cells }] }
})
function download() {
  const rows = [['日期', '浏览量 PV'], ...(data.value?.trend?.pageviews || []).map(p => [p.x, String(p.y)])]
  const text = '\uFEFF' + rows.map(row => row.map(value => `"${String(value).replace(/^[=+@-]/, "'$&").replaceAll('"', '""')}"`).join(',')).join('\r\n')
  const url = URL.createObjectURL(new Blob([text], { type: 'text/csv;charset=utf-8' })); const link = document.createElement('a'); link.href = url; link.download = 'caiya-daily-analytics.csv'; link.click(); setTimeout(() => URL.revokeObjectURL(url), 1000)
}
</script>
<template><div><AdminPageHead title="数据统计" subtitle="看看内容如何被发现，每一个数字都来自真实访问。"><button :disabled="data?.status !== 'available'" @click="download">⇩ 导出日报</button><button @click="refresh()">刷新</button></AdminPageHead><form v-if="!cloudWithoutApi" class="analytics-toolbar studio-panel" @submit.prevent="query"><div class="segmented"><button type="button" @click="range(7)">近 7 天</button><button type="button" @click="range(14)">近 14 天</button><button type="button" @click="range(30)">近 30 天</button></div><div><input v-model="start" type="date" aria-label="开始日期"><span>—</span><input v-model="end" type="date" aria-label="结束日期"><button>查询</button></div></form><div v-if="status === 'pending'" class="studio-panel admin-empty">正在读取统计数据…</div><div v-else-if="cloudWithoutApi" class="studio-panel analytics-empty"><span>▥</span><h2>在 Umami Cloud 查看访问统计</h2><p>本站已配置 Cloud 追踪脚本，可在 Umami 控制台查看浏览量、访客数、来源与访问趋势。</p><p class="admin-footnote">博客后台读取统计需要 API 权限，访问采集不依赖 API。</p><a class="primary" href="https://cloud.umami.is" target="_blank" rel="noopener noreferrer">打开 Umami Cloud ↗</a></div><div v-else-if="error || data?.status !== 'available'" class="studio-panel analytics-empty"><span>▥</span><h2>{{ data?.status === 'unconfigured' ? '让每一次相遇，慢慢有迹可循。' : '统计数据暂时无法加载。' }}</h2><p>{{ data?.message || '请稍后重试。' }}</p><p v-if="data?.status === 'unconfigured'" class="admin-footnote">配置 Umami 服务后，这里会显示浏览量、访客数、来源、设备与内容排行。当前没有生成模拟统计。</p><button @click="refresh()">重新检查连接</button></div><template v-else><div class="metric-grid analytics-metrics"><div v-for="m in metrics" :key="m.key" class="metric-card"><span>{{ m.name }}</span><strong>{{ data?.overview?.[m.key]?.value?.toLocaleString() ?? '—' }}</strong><small v-if="data?.overview?.[m.key]?.prev !== undefined">前期 {{ data.overview[m.key]!.prev!.toLocaleString() }}</small></div></div><div class="dashboard-grid"><section class="studio-panel"><h2>访问趋势</h2><ClientOnly><AnalyticsChart :option="trend" /></ClientOnly><p class="admin-footnote">按北京时间聚合。区间 UV 独立去重，不能用每日访客数直接相加。</p></section><section class="studio-panel"><h2>访问来源</h2><ClientOnly><AnalyticsChart :option="pie(data?.referrer || [])" /></ClientOnly></section></div><div class="dashboard-grid"><section class="studio-panel"><h2>热门内容 · {{ pathMetricLabel }}</h2><div class="table-scroll"><table class="admin-table"><thead><tr><th>页面</th><th>{{ pathMetricLabel }}</th></tr></thead><tbody><tr v-for="p in data?.url?.slice(0, 15)" :key="p.x"><td>{{ p.x }}</td><td>{{ p.y.toLocaleString() }}</td></tr></tbody></table></div></section><section class="studio-panel"><h2>设备与浏览器</h2><ClientOnly><AnalyticsChart :option="pie(data?.device || [])" :height="240" /></ClientOnly><div v-for="p in data?.browser" :key="p.x" class="content-count-row"><span>{{ p.x }}</span><strong>{{ p.y }}</strong></div></section></div><section class="studio-panel"><h2>访问时段 · {{ seriesMetricLabel }}</h2><p class="admin-footnote">各小时数值按星期与时段累加，不代表整个区间去重后的总数。</p><div class="heat-scroll"><ClientOnly><AnalyticsChart :option="heat" :height="250" /></ClientOnly></div></section><p class="admin-footnote">Umami 汇总数据 · 北京时间。零访问与服务连接失败会分别展示。</p></template></div></template>
